'use strict';

// MODULES //

var Uint32Array = require( '@stdlib/array/uint32' );
var toWords = require( '@stdlib/number/int64/base/to-words' ).assign;
var words2int64 = require( '@stdlib/number/int64/ctor' ).of;
var assign = require( './assign.js' );


// VARIABLES //

var WORKSPACE = new Uint32Array( 6 );


// MAIN //

/**
* Multiplies two 64-bit signed integers.
*
* @param {Int64} a - 64-bit signed integer
* @param {Int64} b - 64-bit signed integer
* @returns {Int64} result
*
* @example
* var Int64 = require( '@stdlib/number/int64/ctor' );
*
* var a = new Int64( 5 );
* var b = new Int64( 10 );
*
* var v = mul( a, b );
* // returns <Int64>
*/
function mul( a, b ) {
	toWords( a, WORKSPACE, 1, 0 );
	toWords( b, WORKSPACE, 1, 2 );
	assign( WORKSPACE[ 0 ], WORKSPACE[ 1 ], WORKSPACE[ 2 ], WORKSPACE[ 3 ], WORKSPACE, 1, 4 ); // eslint-disable-line max-len
	return words2int64( WORKSPACE[ 4 ], WORKSPACE[ 5 ] );
}


// EXPORTS //

module.exports = mul;
